          name: 'TypeEnum',
          values: {
            human: { value: 'human' },
            robot: { value: 'robot' },
          },
        });
        const SomeClassType = new GraphQLObjectType({
            name: 'SomeClass',
            fields: {
              nameUpperCase: {
                type: new GraphQLNonNull(GraphQLString),
                resolve: p => p.name.toUpperCase(),
              },
              type: { type: TypeEnum },
              language: {
                type: new GraphQLEnumType({
                  name: 'LanguageEnum',
                  values: {
                    fr: { value: 'fr' },
                    en: { value: 'en' },
                  },
                }),
                resolve: () => 'fr',
              },
            },
          }),
          parseGraphQLServer = new ParseGraphQLServer(parseServer, {
            graphQLPath: '/graphql',
            graphQLCustomTypeDefs: new GraphQLSchema({
              query: new GraphQLObjectType({
                name: 'Query',
                fields: {
                  customQuery: {
                    type: new GraphQLNonNull(GraphQLString),
                    args: {
                      message: { type: new GraphQLNonNull(GraphQLString) },
                    },
                    resolve: (p, { message }) => message,
                  },
                  customQueryWithAutoTypeReturn: {
                    type: SomeClassType,
                    args: {
                      id: { type: new GraphQLNonNull(GraphQLString) },
                    },
                    resolve: async (p, { id }) => {
                      const obj = new Parse.Object('SomeClass');
                      obj.id = id;
                      await obj.fetch();
                      return obj.toJSON();
                    },
                  },
                },
              }),
              types: [
                new GraphQLInputObjectType({
                  name: 'CreateSomeClassFieldsInput',
                  fields: {
                    type: { type: TypeEnum },
                  },
                }),
                new GraphQLInputObjectType({
                  name: 'UpdateSomeClassFieldsInput',
                  fields: {
                    type: { type: TypeEnum },
                  },
                }),
                SomeClassType,
              ],
            }),
          });

        parseGraphQLServer.applyGraphQL(expressApp);
        await new Promise(resolve => httpServer.listen({ port: 13377 }, resolve));
        const httpLink = createUploadLink({
          uri: 'http://localhost:13377/graphql',
          fetch,
          headers,
        });
        apolloClient = new ApolloClient({
          link: httpLink,
          cache: new InMemoryCache(),
          defaultOptions: {
            query: {
              fetchPolicy: 'no-cache',
            },
          },
        });
      })

