before((done) => {
    druidServer = mockDruid({
      onDataSources: function() {
        return {
          json: dataLoaded ? ['wikipedia'] : []
        }
      },
      onQuery: function(query) {
        if (!dataLoaded) {
          return {
            json: []
          };
        }

        switch (query.queryType) {
          case 'segmentMetadata':
            expect(query.dataSource).to.equal('wikipedia');
            return {
              json: segmentMetadataResponse
            };

          case 'timeBoundary':
            expect(query.dataSource).to.equal('wikipedia');
            return {
              json: [
                {
                  "timestamp": "2015-09-12T23:59:00.000Z",
                  "result": {
                    "maxTime": "2015-09-12T23:59:00.000Z"
                  }
                }
              ]
            };

          default:
            throw new Error(`unknown query ${query.queryType}`);
        }
      }
    }, function(err, port) {
      if (err) return done(err);

      swivServer = spawnServer(`bin/turnilo -c test/configs/list-refresh-on-load-datasource.yaml -p ${TEST_PORT}`, {
        env: {
          DRUID_HOST: `localhost:${port}`
        }
      });

      swivServer.onHook(`Cluster 'druid' could not introspect 'wiki' because: No such datasource`, done);
    });
  })

