      ({ nuxt } = await setup({
        ...loadConfig(__dirname),
        content: {
          markdown: {
            async highlighter () {
              const {
                createShikiHighlighter,
                runTwoSlash,
                renderCodeToHTML
              } = require("shiki-twoslash")
              const highlighter = await createShikiHighlighter({
                theme: "nord"
              })
              return (rawCode, lang) => {
